<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';
import {Plane,TrainFront,Hotel,ArrowRight,ArrowLeftRight,MapPin,Link,X,Check,Search,Ticket,RefreshCw,Sun,ShieldCheck} from '@lucide/vue';
interface Session {authenticated:boolean;connected:boolean;user_id?:string;label?:string;bank_label?:string;cities:Record<string,string[]>}
interface Service {id:string;kind:string;name:string;origin:string;destination:string;date:string;departure:string;arrival:string;duration_minutes:number;class_name:string;price_minor:number}
interface Stay {id:string;kind:string;name:string;area:string;address:string;room_type:string;price_minor:number;nights:number;rating:number}
interface Trip {origin:string;destination:string;departure_date:string;return_date:string;area:string;passengers:number;rooms:number}
interface Results {search_id:string;trip:Trip;outbound:Service[];inbound:Service[];hotels:Stay[]}
interface Order {version:number;status_code:string;net_paid_minor:number;id:string;trip:Trip;amount_minor:number;created_at:string;status:string;items:{name:string;kind:string;quantity:number;nights?:number;amount_minor:number}[]}
const session=ref<Session>({authenticated:false,connected:false,cities:{}}),busy=ref(false),error=ref(''),notice=ref('');
const tab=ref('规划旅行'),loginOpen=ref(false),connectOpen=ref(false),phone=ref(''),sms=ref(''),syncCode=ref(''),smsNotice=ref('');
const trip=ref<Trip>({origin:'',destination:'',departure_date:'',return_date:'',area:'',passengers:1,rooms:1});
const results=ref<Results|null>(null),orders=ref<Order[]>([]),outbound=ref(''),inbound=ref(''),hotel=ref(''),filter=ref('all');
const money=(n:number)=>(n/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
function beijingDay(offset:number){const d=new Date(Date.now()+offset*86400000+8*3600000);return d.toISOString().slice(0,10);}
const minDate=beijingDay(1),maxDate=beijingDay(180);
async function api<T>(path:string,body?:unknown):Promise<T>{
 const headers:Record<string,string>={};if(body!==undefined)headers['Content-Type']='application/json';if(session.value.user_id)headers['x-travel-account']=session.value.user_id;
 const res=await fetch('/api/travel'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers,body:body===undefined?undefined:JSON.stringify(body)});
 const value=await res.json();if(!res.ok){if(res.status===401||res.status===409&&String(value.detail).includes('已切换')){clearPrivate();session.value={authenticated:false,connected:false,cities:session.value.cities};loginOpen.value=true;}throw new Error(typeof value.detail==='string'?value.detail:'请检查日期、城市和填写内容。');}return value;
}
function clearPrivate(){results.value=null;orders.value=[];outbound.value='';inbound.value='';hotel.value='';notice.value='';editingOrder.value=null;cancelInstruction.value='';}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await action();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function load(){const next=await api<Session>('/session');if(next.user_id!==session.value.user_id)clearPrivate();session.value=next;}
async function search(){await run(async()=>{if(!session.value.authenticated){loginOpen.value=true;return;}results.value=await api<Results>('/search',trip.value);outbound.value='';inbound.value='';hotel.value='';notice.value='';});}
async function sendSMS(){await run(async()=>{smsNotice.value=(await api<{demo_code:string}>('/auth/sms',{phone:phone.value})).demo_code;});}
async function login(){await run(async()=>{await api('/auth/login',{phone:phone.value,code:sms.value});await load();loginOpen.value=false;sms.value='';smsNotice.value='';});}
async function connect(){await run(async()=>{session.value=await api<Session>('/connect',{code:syncCode.value});connectOpen.value=false;syncCode.value='';notice.value='已关联。现在可以在有数对话中推荐行程和确认预订。';});}
async function logout(){await run(async()=>{await api('/auth/logout',{});clearPrivate();trip.value={origin:'',destination:'',departure_date:'',return_date:'',area:'',passengers:1,rooms:1};phone.value='';sms.value='';syncCode.value='';await load();tab.value='规划旅行';});}
async function showOrders(){tab.value='我的行程';await run(async()=>{if(!session.value.authenticated){loginOpen.value=true;return;}orders.value=(await api<{orders:Order[]}>('/orders')).orders;});}
const editingOrder=ref<Order|null>(null),cancelInstruction=ref('');
async function editOrder(order:Order){editingOrder.value=order;trip.value={...order.trip};tab.value='规划旅行';await search();}
async function cancelOrder(order:Order){cancelInstruction.value=`请免费退订旅行订单 ${order.id} 的全部项目，当前版本${order.version}。请先查询核对并生成确认卡，我自己验证后办理，不要直接退款。`;try{await navigator.clipboard.writeText(cancelInstruction.value);notice.value='已复制整单免费退订指令，请粘贴到有数核对并验证。';}catch{notice.value='请复制下方指令到有数，核对并验证后退订。';}}
const selected=computed(()=>results.value?[results.value.outbound.find(i=>i.id===outbound.value),results.value.inbound.find(i=>i.id===inbound.value),results.value.hotels.find(i=>i.id===hotel.value)]:[]);
const total=computed(()=>selected.value.reduce((n,i)=>n+(i?i.price_minor*('nights' in i?i.nights*results.value!.trip.rooms:results.value!.trip.passengers):0),0));
const instruction=computed(()=>{if(!results.value||selected.value.some(i=>!i)||selected.value.length!==3)return '';const t=results.value.trip;return `${editingOrder.value?'帮我免费改签原旅行订单 '+editingOrder.value.id+' 的去程、返程和酒店，调整为以下明确选择的方案，不要新建重复订单：':'帮我预订演示行程：'}${t.departure_date}从${t.origin}去${t.destination}，${t.return_date}返回，住${t.area}，${t.passengers}人、${t.rooms}间。去程选${selected.value[0]!.name}（${outbound.value}），返程选${selected.value[1]!.name}（${inbound.value}），酒店选${selected.value[2]!.name}。请先从旅行平台重新查询核对这些方案和总价，再生成确认卡，我确认并验证后${editingOrder.value?'办理免费改签，只补退差价':'下单'}。`;});
async function copy(){if(!instruction.value)return;try{await navigator.clipboard.writeText(instruction.value);notice.value='已复制，请粘贴到有数聊天中核对并支付。';}catch{notice.value='请从下方选中并复制行程指令。';}}
function destinationChanged(){trip.value.area='';}
const focus=()=>run(async()=>{await load();if(tab.value==='我的行程'&&session.value.authenticated)orders.value=(await api<{orders:Order[]}>('/orders')).orders;});
onMounted(()=>{void run(load);window.addEventListener('focus',focus);});
onBeforeUnmount(()=>window.removeEventListener('focus',focus));
</script>

<template>
 <div class="travel-app">
  <div class="demo-bar">旅行预订演示 · 虚构班次与酒店 · 仅使用虚拟余额 · 全部免费退改，仅补退差价</div>
  <header class="travel-header"><a class="travel-brand" href="/"><span><Plane :size="26"/></span><div>有数旅行<small>YOUR NEXT CHAPTER</small></div></a><nav><button :class="{active:tab==='规划旅行'}" @click="tab='规划旅行'">规划旅行</button><button :class="{active:tab==='我的行程'}" @click="showOrders">我的行程</button></nav><div class="header-account"><button class="pair-button" :disabled="session.connected" @click="session.authenticated?connectOpen=true:loginOpen=true"><Check v-if="session.connected" :size="15"/><Link v-else :size="15"/>{{session.connected?'已关联 '+session.bank_label:'关联有数'}}</button><button v-if="!session.authenticated" class="blue-button" @click="loginOpen=true">手机号登录</button><template v-else><small>{{session.label}}</small><button @click="logout" :disabled="busy">退出</button></template></div></header>
  <main>
   <div v-if="error" class="travel-error" role="alert">{{error}}<button aria-label="关闭错误" @click="error=''">×</button></div>
   <template v-if="tab==='规划旅行'">
    <section class="travel-hero"><div class="hero-copy"><span class="hero-kicker"><Sun :size="15"/> LET THE JOURNEY BEGIN</span><h1>把期待的远方，<br/>安排进下一段日常。</h1><p>机票、动车与酒店，一起找到适合你的旅行方案。</p><div class="hero-pills"><span><ShieldCheck :size="14"/>确认后模拟预订</span><span><MapPin :size="14"/>20 座演示城市</span></div></div><div class="journey-art" aria-hidden="true"><div class="sun-disc"></div><div class="mountain mountain-back"></div><div class="mountain mountain-front"></div><div class="lake"></div><Plane class="hero-plane" :size="64"/><span class="art-caption">A LITTLE FURTHER, A LITTLE FREER.</span><div class="floating-ticket"><Ticket :size="24"/><div>下一站，心之所向<small>TRAVEL WELL · LIVE FULLY</small></div></div></div></section>
    <form class="trip-search" @submit.prevent="search"><div class="search-caption"><span><Plane :size="16"/>机票</span><span><TrainFront :size="16"/>动车</span><span><Hotel :size="16"/>酒店</span><small>往返交通 + 目的地住宿</small></div><div class="search-fields"><label>出发城市<select v-model="trip.origin" required aria-label="出发城市"><option value="" disabled>从哪里出发</option><option v-for="(_,city) in session.cities" :key="city">{{city}}</option></select></label><ArrowLeftRight class="swap-icon" :size="18"/><label>目的地<select v-model="trip.destination" @change="destinationChanged" required aria-label="目的地"><option value="" disabled>想去哪里</option><option v-for="(_,city) in session.cities" :key="city">{{city}}</option></select></label><label class="trip-date">出发 / 入住<input v-model="trip.departure_date" type="date" required :min="minDate" :max="maxDate" aria-label="出发日期"/></label><label class="trip-date">返程 / 退房<input v-model="trip.return_date" type="date" required :min="trip.departure_date||minDate" aria-label="返程日期"/></label><label>住宿区域<select v-model="trip.area" required aria-label="住宿区域"><option value="" disabled>选择区域</option><option value="不限">不限区域</option><option v-for="area in session.cities[trip.destination]||[]" :key="area">{{area}}</option></select></label><button class="blue-button search-button" :disabled="busy"><Search :size="18"/>{{busy?'查询中…':'搜索行程'}}</button></div><div class="trip-counts"><label>出行人数 <select v-model.number="trip.passengers" aria-label="出行人数"><option v-for="n in 6" :key="n" :value="n">{{n}} 人</option></select></label><label>房间数 <select v-model.number="trip.rooms" aria-label="房间数"><option v-for="n in 3" :key="n" :value="n">{{n}} 间</option></select></label><small>默认 1 人、1 间 · 酒店按入住晚数计价 · 演示票价已含税费</small></div></form>
    <section v-if="!results" class="travel-start"><div><h2>一句话，开启一段旅行</h2><p>在有数里告诉我日期、出发地、目的地和住宿区域，我会帮你推荐。</p><blockquote>“下周五从上海去杭州，周日返回，住西湖区，帮我看看机票、动车和酒店。”</blockquote><small>先关联账户，再到有数对话中选择方案，确认并验证后模拟扣款。</small></div><div class="start-steps"><p><b>01</b><span>选择合适的交通与酒店</span></p><p><b>02</b><span>核对人数、日期与总价</span></p><p><b>03</b><span>在有数确认支付，行程同步到这里</span></p></div></section>
    <template v-else><div class="results-heading"><div><span class="section-kicker">YOUR JOURNEY</span><h2>{{results.trip.origin}} <ArrowRight :size="21"/> {{results.trip.destination}}</h2><p>{{results.trip.departure_date}} 至 {{results.trip.return_date}} · {{results.trip.passengers}} 人 · {{results.trip.rooms}} 间</p></div><div class="mode-filter"><button v-for="mode in [['all','全部交通'],['flight','只看机票'],['train','只看动车']]" :key="mode[0]" :class="{selected:filter===mode[0]}" @click="filter=mode[0]">{{mode[1]}}</button></div></div>
     <div class="transport-grid"><section v-for="leg in ['outbound','inbound'] as const" :key="leg" class="transport-section"><h3><span>{{leg==='outbound'?'去':'返'}}</span>{{leg==='outbound'?'去程交通':'返程交通'}}<small>每程选择一种交通方式</small></h3><button v-for="item in results[leg].filter(i=>filter==='all'||i.kind===filter)" :key="item.id" class="service-card" :class="{chosen:(leg==='outbound'?outbound:inbound)===item.id}" @click="leg==='outbound'?outbound=item.id:inbound=item.id"><div class="service-top"><span><Plane v-if="item.kind==='flight'" :size="14"/><TrainFront v-else :size="14"/>{{item.name}}</span><small>{{item.class_name}}</small><Check v-if="(leg==='outbound'?outbound:inbound)===item.id" :size="15"/></div><div class="service-times"><div><strong>{{item.departure}}</strong><small>{{item.origin}}</small></div><div class="travel-duration"><small>{{Math.floor(item.duration_minutes/60)}}小时{{item.duration_minutes%60}}分</small><i></i></div><div><strong>{{item.arrival}}</strong><small>{{item.destination}}</small></div><div class="service-price"><b>¥{{money(item.price_minor)}}</b><small>/ 人</small></div></div></button></section></div>
     <section class="hotel-section"><div class="results-heading"><div><span class="section-kicker">STAY A LITTLE LONGER</span><h2>住在{{results.trip.area==='不限'?'喜欢的地方':results.trip.area}}</h2><p>入住 {{results.trip.departure_date}} · 退房 {{results.trip.return_date}} · {{results.hotels[0]?.nights}} 晚</p></div></div><div class="hotel-grid"><button v-for="(stay,i) in results.hotels" :key="stay.id" class="hotel-card" :class="{chosen:hotel===stay.id}" @click="hotel=stay.id"><div class="hotel-art" :class="'hotel-art-'+i%3"><div class="building"><i v-for="n in 9" :key="n"></i></div><span>{{stay.area}}</span><b v-if="hotel===stay.id"><Check :size="17"/></b></div><div class="hotel-info"><h3>{{stay.name}}</h3><p><MapPin :size="12"/>{{stay.address}}</p><div class="hotel-rating"><b>{{stay.rating.toFixed(1)}}</b> 演示评分 · {{stay.room_type}}</div><div class="hotel-price"><small>每间每晚</small><strong>¥{{money(stay.price_minor)}}</strong></div></div></button></div></section>
     <section class="travel-summary"><div><span class="section-kicker">YOUR SELECTION</span><h3>{{editingOrder?'改签方案':'预订方案'}} · 已选 {{selected.filter(Boolean).length}} / 3 项</h3><p v-if="editingOrder">正在修改订单 {{editingOrder.id}}<button class="pair-button" @click="editingOrder=null">改为新预订</button></p><p>往返交通 + 酒店，共 {{results.trip.passengers}} 人、{{results.trip.rooms}} 间</p></div><div class="summary-price"><small>所选项目合计</small><strong>¥{{money(total)}}</strong></div><button class="blue-button" :disabled="!instruction||!session.connected" @click="copy">复制给有数确认 <ArrowRight :size="17"/></button><p v-if="!session.connected" class="link-hint">先关联有数账户，再继续预订。</p><textarea v-if="instruction" readonly :value="instruction" aria-label="有数旅行预订指令"></textarea><p v-if="notice" class="travel-notice" role="status">{{notice}}</p></section>
    </template>
   </template>
   <template v-else><div class="results-heading"><div><span class="section-kicker">MY TRIPS</span><h1>我的行程</h1><p>在有数完成确认支付的模拟预订，会显示在这里。</p></div><button class="pair-button" :disabled="busy" @click="showOrders"><RefreshCw :size="14"/>刷新</button></div><div v-if="!orders.length" class="travel-empty"><Ticket :size="35"/><h3>还没有旅行订单</h3><p>{{!session.authenticated?'请先使用手机号登录。':!session.connected?'请先关联有数账户。':'先规划一段旅行，在有数确认后即可同步。'}}</p><button class="blue-button" @click="tab='规划旅行'">去规划旅行</button></div><article v-for="order in orders" :key="order.id" class="trip-order"><div><h3>{{order.trip.origin}} → {{order.trip.destination}}</h3><span>{{order.status}}</span></div><p>{{order.trip.departure_date}} 至 {{order.trip.return_date}} · {{order.trip.passengers}} 人 · {{order.trip.rooms}} 间</p><ul><li v-for="item in order.items" :key="item.name">{{item.name}}<span>¥{{money(item.amount_minor)}}</span></li></ul><footer><small>{{order.id}}</small><strong>{{order.status_code==='cancelled'?'已全额退款':'当前实付'}} ¥{{money(order.status_code==='cancelled'?order.amount_minor:order.net_paid_minor)}}</strong></footer><div v-if="order.status_code==='active'" class="order-actions"><button class="pair-button" @click="editOrder(order)">免费改签</button><button class="pair-button" @click="cancelOrder(order)">整单免费退订指令</button></div><small>免费退改，手续费 ¥0.00，仅补退差价。虚拟预订，不真实出票或提供住宿。</small></article><section v-if="cancelInstruction" class="travel-summary"><p>{{notice}}</p><textarea readonly :value="cancelInstruction" aria-label="免费退订指令"></textarea></section></template>
   <footer class="travel-footer"><strong>有数旅行 · 仿携程功能演示</strong><span>全部班次、酒店、评分与价格为虚构测试数据，仅扣虚拟账户。</span></footer>
  </main>
  <div v-if="loginOpen||connectOpen" class="travel-overlay" @click.self="loginOpen=false;connectOpen=false"><section class="travel-modal" role="dialog" aria-modal="true" :aria-label="loginOpen?'旅行手机号登录':'关联有数账户'"><button class="modal-close" aria-label="关闭弹窗" @click="loginOpen=false;connectOpen=false"><X :size="20"/></button><div class="modal-symbol"><Plane v-if="loginOpen" :size="28"/><Link v-else :size="28"/></div><h2>{{loginOpen?'欢迎来到有数旅行':'关联有数账户'}}</h2><p>{{loginOpen?'手机号短信登录，旅行账户独立保存。演示账号：11111111111。':'在有数应用设置中生成通用同步码，并填写到下方。与证券、外卖使用同一个码。'}}</p><form v-if="loginOpen" @submit.prevent="login"><label>手机号<input v-model="phone" inputmode="tel" pattern="1[0-9]{10}" maxlength="11" required aria-label="旅行登录手机号"/></label><label>短信验证码<div class="sms-field"><input v-model="sms" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required aria-label="旅行登录验证码"/><button type="button" :disabled="busy" @click="sendSMS">获取验证码</button></div></label><button class="blue-button full" :disabled="busy">登录 / 注册</button></form><form v-else @submit.prevent="connect"><label>8 位通用同步码<input v-model="syncCode" inputmode="numeric" pattern="[0-9]{8}" maxlength="8" required aria-label="旅行通用同步码"/></label><button class="blue-button full" :disabled="busy">确认关联</button></form><p v-if="error" class="modal-error" role="alert">{{error}}</p></section></div>
  <div v-if="smsNotice" class="travel-sms" role="status"><button aria-label="关闭短信提示" @click="smsNotice=''"><X :size="15"/></button><strong>演示短信 · 有数旅行</strong><p>验证码 <b>{{smsNotice}}</b></p><small>5 分钟有效，未向真实手机发送短信。</small></div>
 </div>
</template>

<style>
